await cdp('Network.enable');await cdp('Network.setCacheDisabled',{cacheDisabled:true});await cdp('Network.setBlockedURLs',{urls:['*fonts.googleapis.com*','*fonts.gstatic.com*']});
const E=async x=>{const r=await ev(x);if(r.subtype==='error')throw Error(r.description);return r.value;};const wait=async()=>new Promise(r=>setTimeout(r,500));const check=async(n,x)=>{if(!await E(x))throw Error('FAIL '+n);console.log('PASS',n)};const click=async s=>{await E(`document.querySelector(${JSON.stringify(s)}).click()`);await wait();};
await nav('buyer/home.html');await wait();
const ids=await E(`(async()=>{const {models}=await import('/assets/js/data.js');const {newestModels}=await import('/assets/js/merchandising-data.js');return newestModels(models).map(m=>m.id)})()`);
await check('four date-ranked topics',`JSON.stringify([...document.querySelectorAll('[data-slide-model]')].map(n=>n.dataset.slideModel))===${JSON.stringify(JSON.stringify(ids))}&&document.querySelectorAll('.home-newest-slide:not([hidden])').length===1`);
await click('[data-newest-step="-1"]');await check('previous wraps','document.querySelector(".home-newest").dataset.modelId==='+JSON.stringify(ids.at(-1)));await click('[data-newest-step="1"]');await check('next wraps to newest','document.querySelector(".home-newest").dataset.modelId==='+JSON.stringify(ids[0]));
for(let i=0;i<ids.length;i++){await click('[data-newest-index="'+i+'"]');await check('correct CTA '+ids[i],`[...document.querySelectorAll('.home-newest-slide:not([hidden]) a')].every(a=>new URL(a.href).searchParams.get('id')===${JSON.stringify(ids[i])})&&document.querySelector('[data-newest-index="${i}"]').getAttribute('aria-pressed')==='true'`);}
await E(`document.querySelector('[data-newest-index="0"]').focus()`);await cdp('Input.dispatchKeyEvent',{type:'keyDown',key:'ArrowRight',code:'ArrowRight',windowsVirtualKeyCode:39});await cdp('Input.dispatchKeyEvent',{type:'keyUp',key:'ArrowRight',code:'ArrowRight',windowsVirtualKeyCode:39});await check('keyboard updates slide and dot focus','document.activeElement.dataset.newestIndex==="0"&&document.querySelector(".home-newest").dataset.modelId==='+JSON.stringify(ids[0]));
await E('document.querySelector(".home-newest").dispatchEvent(new KeyboardEvent("keydown",{key:"End",bubbles:true}))');await check('End selects last','document.querySelector(".home-newest").dataset.modelId==='+JSON.stringify(ids.at(-1)));
await E('document.querySelector(".home-newest-slide:not([hidden]) a").click()');await wait();await check('CTA opens model of current slide','new URLSearchParams(location.search).get("id")==='+JSON.stringify(ids.at(-1)));
for(const width of [360,768,1440]){await cdp('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});await nav('buyer/home.html');await wait();await E('document.querySelector(".home-newest").scrollIntoView({block:"start"})');await wait();for(let i=0;i<ids.length;i++){await click('[data-newest-index="'+i+'"]');await check('slide layout '+width+' '+i,'document.documentElement.scrollWidth<=innerWidth&&[...document.querySelectorAll(".home-newest-slide:not([hidden]) a")].every(a=>{const r=a.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.height>=44})');await check('image loaded '+width+' '+i,'document.querySelector(".home-newest-slide:not([hidden]) img").naturalWidth>0');}await click('[data-newest-index="0"]');fs.writeFileSync('/tmp/pcmatch-carousel-'+width+'.png',Buffer.from((await cdp('Page.captureScreenshot',{format:'png'})).data,'base64'));}
await E(`(()=>{const stage=document.querySelector('.home-newest-stage');const start=new Event('touchstart');start.touches=[{clientX:220,clientY:50}];stage.dispatchEvent(start);const end=new Event('touchend');end.changedTouches=[{clientX:90,clientY:55}];stage.dispatchEvent(end)})()`);await check('horizontal swipe advances','document.querySelector(".home-newest").dataset.modelId==='+JSON.stringify(ids[1]));
await E('document.querySelector(".home-newest-slide:not([hidden]) img").src="/missing-carousel-image.png"');await wait();await check('image fallback on later slide','document.querySelector(".home-newest-slide:not([hidden]) img").hidden&&!document.querySelector(".home-newest-slide:not([hidden]) .image-fallback").hidden');
await E(`(async()=>{const {models}=await import('/assets/js/data.js');models.slice(1).forEach(m=>m.createdAt='invalid');const {home}=await import('/assets/js/home.js');home()})()`);await check('one valid model hides unnecessary controls','document.querySelectorAll(".home-newest-slide").length===1&&document.querySelector(".home-newest-controls").hidden');
await E(`(async()=>{const {models}=await import('/assets/js/data.js');models.forEach(m=>m.createdAt='invalid');const {home}=await import('/assets/js/home.js');home()})()`);await check('no valid model hides carousel','document.querySelector(".home-newest").hidden');
